DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def _check_base(base):
    if not isinstance(base, int) or isinstance(base, bool) or not 2 <= base <= 36:
        raise ValueError(f"base must be an integer from 2 to 36, got {base!r}")


def to_base(number, base):
    _check_base(base)
    if number == 0:
        return "0"
    sign = "-" if number < 0 else ""
    n = abs(number)
    out = []
    while n:
        n, r = divmod(n, base)
        out.append(DIGITS[r])
    return sign + "".join(reversed(out))


def from_base(text, base):
    _check_base(base)
    if not isinstance(text, str):
        raise ValueError(f"text must be a string, got {text!r}")
    body = text
    negative = False
    if body.startswith("-"):
        negative = True
        body = body[1:]
    if not body:
        raise ValueError(f"no digits in {text!r}")
    value = 0
    for ch in body:
        if ch.isascii() and ch.isalnum():
            d = DIGITS.find(ch.lower())
        else:
            d = -1
        if d < 0 or d >= base:
            raise ValueError(f"invalid digit {ch!r} for base {base}")
        value = value * base + d
    return -value if negative else value
